// Writes proxy/src/screen/milranges.gen.ts from the FIRMWARE's military table, src/SpecialAircraft.cpp's MIL_RANGES
// (the screen service's class rules, phase 1: the app's PRIVATE rule names the firmware's table, not
// proxy/src/military.ts's). The generated file is committed; this script only writes it.
//
// ONE CHECK, AND IT IS NOT HERE. scripts/check-screen.ts's P-E3 compares the committed file with the firmware's table
// on every run, with a sabotage (E3s) proving it can fail. A --check mode here would be a second guard on the same
// rule, and two guards on one rule drift (CLAUDE.md: the device-id allowlist's two inline lists diverged in minutes).
//
//   node scripts/gen-screen-milranges.mjs    rewrite the file; prints the range count; exit 2 if none is read
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const PROXY = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const FIRMWARE = join(PROXY, "..", "src", "SpecialAircraft.cpp");
const OUT = join(PROXY, "src", "screen", "milranges.gen.ts");
const ANCHOR = "constexpr Range MIL_RANGES[] = {";

const src = readFileSync(FIRMWARE, "utf8");
const at = src.indexOf(ANCHOR);
const end = at < 0 ? -1 : src.indexOf("};", at + ANCHOR.length);
const pairs = at < 0 || end < 0 ? [] : [...src.slice(at + ANCHOR.length, end).matchAll(/\{\s*0x([0-9A-Fa-f]+)\s*,\s*0x([0-9A-Fa-f]+)\s*\}/g)];
if (pairs.length === 0) {
  console.error(`no MIL_RANGES read from ${FIRMWARE}`);
  process.exit(2);
}
const hex = (s) => `0x${s.toLowerCase().padStart(6, "0")}`;
const rows = pairs.map((m) => `  [${hex(m[1])}, ${hex(m[2])}],`).join("\n");
writeFileSync(
  OUT,
  `// GENERATED by scripts/gen-screen-milranges.mjs from src/SpecialAircraft.cpp's MIL_RANGES. Do not edit:
// scripts/check-screen.ts (P-E3) refuses any difference from the firmware's table.
export const MIL_RANGES: ReadonlyArray<readonly [number, number]> = [
${rows}
];
`,
);
console.log(`wrote ${pairs.length} ranges to src/screen/milranges.gen.ts`);
